import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.CFuv5BrO.js";const _=JSON.parse('{"title":"入口与交互","description":"Hearth 如何通过任务卡、审批、产物和接管，把多个入口收束成一个注意力界面。","frontmatter":{"title":"入口与交互","description":"Hearth 如何通过任务卡、审批、产物和接管，把多个入口收束成一个注意力界面。","outline":false},"headers":[],"relativePath":"design/experience.md","filePath":"design/experience.md","lastUpdated":1794305977000}'),o={name:"design/experience.md"};function p(i,t,c,n,s,h){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="入口与交互" tabindex="-1">入口与交互 <a class="header-anchor" href="#入口与交互" aria-label="Permalink to &quot;入口与交互&quot;">​</a></h1><p class="lead">Hearth 的入口不是一个无限聊天窗口，而是一个围绕任务、审批、产物和接管组织起来的操作界面。用户不需要理解内部由谁执行，只需要知道系统正在做什么、哪里需要自己，以及结果是否值得信任。</p><h2 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to &quot;设计目标&quot;">​</a></h2><p>入口要解决的核心问题是注意力，而不是信息量。用户打开 Hearth 时，应该先看到正在运行的任务、等待自己决定的动作、最近交付的产物和需要恢复的失败，而不是一长串对话记录。</p><p>网页、命令行、手机和即时消息都可以成为入口，但它们共享同一套任务事实。用户可以在电脑上创建任务，在手机上批准，再回到网页查看产物；设备只是不同的观察和操作方式，不会产生互相对不上的状态。</p><p>通知必须克制。系统只在真正需要用户判断、授权或接管时打断，并且一次通知要说清楚发生了什么、建议怎么做、不处理会有什么后果。普通的进度变化应该留在任务页，不占用用户的时间。</p><p>移动端优先覆盖审批、查看产物、暂停和接管，不追求把桌面端的全部管理功能搬到手机上。界面还要保证键盘操作、可读对比度、屏幕阅读和弱网恢复，因为这些能力直接决定长期使用是否舒服。</p><h2 id="首次运行、多入口与提醒" tabindex="-1">首次运行、多入口与提醒 <a class="header-anchor" href="#首次运行、多入口与提醒" aria-label="Permalink to &quot;首次运行、多入口与提醒&quot;">​</a></h2><p>首次运行不再要求用户先理解“模型档案、执行器绑定、聊天模型”三层概念。全新实例打开根路径时会进入 <code>/welcome</code> 四步向导：选择服务商并测试连接、检查执行器、选择记忆与主动偏好、进入聊天。向导通过一次 <code>PUT /api/model-settings</code> 完成建档、设为聊天模型，并由 <code>setChatProfile</code> 自动绑定原生执行器。只有“没有向导状态且聊天模型未配置”时才强制进入；查询失败、其他路由和已完成设置的用户都不会被挡住。</p><p>主界面之外，导航现在直接暴露“需要你”“记忆”“技能”“邮件”和“设置 → 连接”。“需要你”显示主动建议的待处理数量；主动设置、桌面通知开关、飞书长连接和邮件账户都在设置或邮件工作台内完成，不再依赖只能通过 API 访问的页面。</p><p>通知分两层：页面打开时使用应用内 toast，并可选申请浏览器桌面通知；页面关闭后不承诺推送。需要跨设备、离开电脑也能收到审批时，使用飞书长连接入口——任务状态、审批摘要和一次性审批命令会发到已映射的会话。飞书首版使用文本命令 <code>/approve</code>、<code>/reject</code>，因为卡片按钮回调不支持长连接。</p><p>Web 端已经提供可安装 PWA 壳、离线应用壳和移动底部导航；任务详情展示验收条件、完成结论、缺失证据、产物和最终结果。手机配对、系统级推送和远程接管仍未验收，因此不能把现有 PWA 壳写成完整移动客户端。</p><p>邮件工作台提供账户、收件箱和写信三个视图。IMAP 只读同步把最近邮件写入来源，不标记已读；写信只创建草稿并生成一次性审批，批准后才通过 SMTP 发送并保存回执。真实账户、退信语义和附件选择仍需人工验收。</p><h2 id="设计取舍" tabindex="-1">设计取舍 <a class="header-anchor" href="#设计取舍" aria-label="Permalink to &quot;设计取舍&quot;">​</a></h2><p>任务卡优先于聊天记录。聊天适合表达意图，但长任务需要状态、截止时间、产物和失败恢复；把聊天当作唯一界面，会让用户不断向上翻找，也无法判断哪一步已经真正完成。</p><table tabindex="0"><thead><tr><th>取舍</th><th>Hearth 的选择</th><th>原因</th></tr></thead><tbody><tr><td>主界面</td><td>任务卡、审批卡和产物中心</td><td>用户直接看到工作状态和下一步，而不是解析对话</td></tr><tr><td>多入口</td><td>统一归一化来源、身份和去重</td><td>同一个请求从邮件、网页或消息重复到达时只处理一次</td></tr><tr><td>状态来源</td><td>服务端记录重建界面</td><td>刷新、换设备和重连后仍然一致，不依赖浏览器临时状态</td></tr><tr><td>打断策略</td><td>按风险和等待时间决定</td><td>高风险动作尽快提醒，普通进度不制造通知疲劳</td></tr><tr><td>手机范围</td><td>审批、查看、接管和简单发起</td><td>手机适合短动作，复杂编辑仍留在桌面端</td></tr><tr><td>设备能力</td><td>设备注册时声明能力，不假设全部对等</td><td>有的设备能操作桌面软件，有的只能查看和审批</td></tr></tbody></table><p>界面只发出命令，不直接改写任务事实。用户点击“批准”后，系统要重新检查审批是否过期、动作参数是否变化、授权范围是否仍然有效，再把结果写入记录并更新界面。这样即使两个设备同时操作，也不会出现界面显示成功但实际没有执行的情况。</p><p>失败时界面要诚实：连接中断显示离线，状态不确定显示正在核对，执行器失败显示原因和可恢复动作，不能把“还在尝试”伪装成“已经完成”。当用户选择接管时，系统先暂停自动执行，保存当前进度，再把可操作的范围交给用户。</p>',18)])])}const m=e(o,[["render",p]]);export{_ as __pageData,m as default};
